    25→using Nethermind.Logging;
    26→using Nethermind.Specs.Forks;
    27→using Nethermind.State;
    28→using static Nethermind.Consensus.Processing.IBlockProcessor;
    29→
    30→namespace Nethermind.Consensus.Processing;
    31→
    32→public partial class BlockProcessor(
    33→    ISpecProvider specProvider,
    34→    IBlockValidator blockValidator,
    35→    IRewardCalculator rewardCalculator,
    36→    IBlockTransactionsExecutor blockTransactionsExecutor,
    37→    IWorldState stateProvider,
    38→    IReceiptStorage receiptStorage,
    39→    IBeaconBlockRootHandler beaconBlockRootHandler,
    40→    IBlockhashStore blockHashStore,
    41→    ILogManager logManager,
    42→    IWithdrawalProcessor withdrawalProcessor,
    43→    IExecutionRequestsProcessor executionRequestsProcessor)
    44→    : IBlockProcessor
    45→{
    46→    private readonly ILogger _logger = logManager.GetClassLogger();
    47→    protected readonly WorldStateMetricsDecorator _stateProvider = new WorldStateMetricsDecorator(stateProvider);
    48→    private readonly IReceiptsRootCalculator _receiptsRootCalculator = ReceiptsRootCalculator.Instance;
    49→
    50→    /// <summary>
    51→    /// We use a single receipt tracer for all blocks. Internally receipt tracer forwards most of the calls
    52→    /// to any block-specific tracers.
    53→    /// </summary>
    54→    protected BlockReceiptsTracer ReceiptsTracer { get; set; } = new();
    55→
    56→    public (Block Block, TxReceipt[] Receipts) ProcessOne(Block suggestedBlock, ProcessingOptions options, IBlockTracer blockTracer, IReleaseSpec spec, CancellationToken token)
    57→    {
    58→        if (_logger.IsTrace) _logger.Trace($"Processing block {suggestedBlock.ToString(Block.Format.Short)} ({options})");
    59→
    60→        ApplyDaoTransition(suggestedBlock);
    61→        Block block = PrepareBlockForProcessing(suggestedBlock);
    62→        TxReceipt[] receipts = ProcessBlock(block, blockTracer, options, spec, token);
    63→        ValidateProcessedBlock(suggestedBlock, options, block, receipts);
    64→        if (options.ContainsFlag(ProcessingOptions.StoreReceipts))
    65→        {
    66→            StoreTxReceipts(block, receipts, spec);
    67→        }
    68→
    69→        return (block, receipts);
    70→    }
    71→
    72→    private void ValidateProcessedBlock(Block suggestedBlock, ProcessingOptions options, Block block, TxReceipt[] receipts)
    73→    {
    74→        if (!options.ContainsFlag(ProcessingOptions.NoValidation) && !blockValidator.ValidateProcessedBlock(block, receipts, suggestedBlock, out string? error))
    75→        {
    76→            if (_logger.IsWarn) _logger.Warn(InvalidBlockHelper.GetMessage(suggestedBlock, "invalid block after processing"));
    77→            throw new InvalidBlockException(suggestedBlock, error);
    78→        }
    79→
    80→        // Block is valid, copy the account changes as we use the suggested block not the processed one
    81→        suggestedBlock.AccountChanges = block.AccountChanges;
    82→        suggestedBlock.ExecutionRequests = block.ExecutionRequests;
    83→    }
    84→
    85→    private bool ShouldComputeStateRoot(BlockHeader header) =>
    86→        !header.IsGenesis || !specProvider.GenesisStateUnavailable;
    87→
    88→    protected virtual TxReceipt[] ProcessBlock(
    89→        Block block,
    90→        IBlockTracer blockTracer,
    91→        ProcessingOptions options,
    92→        IReleaseSpec spec,
    93→        CancellationToken token)
    94→    {
    95→        BlockHeader header = block.Header;
    96→
    97→        ReceiptsTracer.SetOtherTracer(blockTracer);
    98→        ReceiptsTracer.StartNewBlockTrace(block);
    99→
   100→        blockTransactionsExecutor.SetBlockExecutionContext(new BlockExecutionContext(block.Header, spec));
   101→
   102→        StoreBeaconRoot(block, spec);
   103→        blockHashStore.ApplyBlockhashStateChanges(header, spec);
   104→        _stateProvider.Commit(spec, commitRoots: false);
   105→
   106→        TxReceipt[] receipts = blockTransactionsExecutor.ProcessTransactions(block, options, ReceiptsTracer, token);
   107→
   108→        _stateProvider.Commit(spec, commitRoots: false);
   109→
   110→        CalculateBlooms(receipts);
   111→
   112→        if (spec.IsEip4844Enabled)
   113→        {
   114→            header.BlobGasUsed = BlobGasCalculator.CalculateBlobGas(block.Transactions);
   115→        }
   116→
   117→        header.ReceiptsRoot = _receiptsRootCalculator.GetReceiptsRoot(receipts, spec, block.ReceiptsRoot);
   118→        ApplyMinerRewards(block, blockTracer, spec);
   119→        withdrawalProcessor.ProcessWithdrawals(block, spec);
   120→
   121→        // We need to do a commit here as in _executionRequestsProcessor while executing system transactions
   122→        // we do WorldState.Commit(SystemTransactionReleaseSpec.Instance). In SystemTransactionReleaseSpec
   123→        // Eip158Enabled=false, so we end up persisting empty accounts created while processing withdrawals.
   124→        _stateProvider.Commit(spec, commitRoots: false);
   125→
   126→        executionRequestsProcessor.ProcessExecutionRequests(block, _stateProvider, receipts, spec);
   127→
   128→        ReceiptsTracer.EndBlockTrace();
   129→
   130→        _stateProvider.Commit(spec, commitRoots: true);
   131→
   132→        if (BlockchainProcessor.IsMainProcessingThread)
   133→        {
   134→            // Get the accounts that have been changed
   135→            block.AccountChanges = _stateProvider.GetAccountChanges();
   136→        }
   137→
   138→        if (ShouldComputeStateRoot(header))
   139→        {
   140→            _stateProvider.RecalculateStateRoot();
   141→            header.StateRoot = _stateProvider.StateRoot;
   142→        }
   143→
   144→        header.Hash = header.CalculateHash();
   145→
   146→        return receipts;
   147→    }
   148→
   149→    [MethodImpl(MethodImplOptions.NoInlining)]
   150→    private static void CalculateBlooms(TxReceipt[] receipts)
   151→    {
   152→        ParallelUnbalancedWork.For(
   153→            0,
   154→            receipts.Length,
   155→            ParallelUnbalancedWork.DefaultOptions,
   156→            receipts,
   157→            static (i, receipts) =>
   158→            {
   159→                receipts[i].CalculateBloom();
   160→                return receipts;
   161→            });
   162→    }
   163→
   164→    private void StoreBeaconRoot(Block block, IReleaseSpec spec)
   165→    {
   166→        try
   167→        {
   168→            beaconBlockRootHandler.StoreBeaconRoot(block, spec, NullTxTracer.Instance);
   169→        }
   170→        catch (Exception e)
   171→        {
   172→            if (_logger.IsWarn) _logger.Warn($"Storing beacon block root for block {block.ToString(Block.Format.FullHashAndNumber)} failed: {e}");
   173→        }
   174→    }
   175→
   176→    private void StoreTxReceipts(Block block, TxReceipt[] txReceipts, IReleaseSpec spec)
   177→    {
   178→        // Setting canonical is done when the BlockAddedToMain event is fired
   179→        receiptStorage.Insert(block, txReceipts, spec, false);
   180→    }
   181→
   182→    private Block PrepareBlockForProcessing(Block suggestedBlock)
   183→    {
   184→        if (_logger.IsTrace) _logger.Trace($"{suggestedBlock.Header.ToString(BlockHeader.Format.Full)}");
   185→        BlockHeader bh = suggestedBlock.Header;
   186→        BlockHeader headerForProcessing = new(
   187→            bh.ParentHash,
   188→            bh.UnclesHash,
   189→            bh.Beneficiary,
   190→            bh.Difficulty,
   191→            bh.Number,
   192→            bh.GasLimit,
   193→            bh.Timestamp,
   194→            bh.ExtraData,
   195→            bh.BlobGasUsed,
   196→            bh.ExcessBlobGas)
   197→        {
   198→            Bloom = Bloom.Empty,
   199→            Author = bh.Author,
   200→            Hash = bh.Hash,
   201→            MixHash = bh.MixHash,
   202→            Nonce = bh.Nonce,
   203→            TxRoot = bh.TxRoot,
   204→            TotalDifficulty = bh.TotalDifficulty,
   205→            AuRaStep = bh.AuRaStep,
   206→            AuRaSignature = bh.AuRaSignature,
   207→            ReceiptsRoot = bh.ReceiptsRoot,
   208→            BaseFeePerGas = bh.BaseFeePerGas,
   209→            WithdrawalsRoot = bh.WithdrawalsRoot,
   210→            RequestsHash = bh.RequestsHash,
   211→            IsPostMerge = bh.IsPostMerge,
   212→            ParentBeaconBlockRoot = bh.ParentBeaconBlockRoot
   213→        };
   214→
   215→        if (!ShouldComputeStateRoot(bh))
   216→        {
   217→            headerForProcessing.StateRoot = bh.StateRoot;
   218→        }
   219→
   220→        return suggestedBlock.WithReplacedHeader(headerForProcessing);
   221→    }
   222→
   223→    private void ApplyMinerRewards(Block block, IBlockTracer tracer, IReleaseSpec spec)
   224→    {
   225→        if (_logger.IsTrace) _logger.Trace("Applying miner rewards:");
   226→        BlockReward[] rewards = rewardCalculator.CalculateRewards(block);
   227→        for (int i = 0; i < rewards.Length; i++)
   228→        {
   229→            BlockReward reward = rewards[i];
   230→
   231→            using ITxTracer txTracer = tracer.IsTracingRewards
   232→                ? // we need this tracer to be able to track any potential miner account creation
   233→                tracer.StartNewTxTrace(null)
   234→                : NullTxTracer.Instance;
   235→
   236→            ApplyMinerReward(block, reward, spec);
   237→
   238→            if (tracer.IsTracingRewards)
   239→            {
   240→                tracer.EndTxTrace();
   241→                tracer.ReportReward(reward.Address, reward.RewardType.ToLowerString(), reward.Value);
   242→                if (txTracer.IsTracingState)
   243→                {
   244→                    _stateProvider.Commit(spec, txTracer);
   245→                }
   246→            }
   247→        }
   248→    }
   249→
